package com.dtm.platform;
import com.dtm.platform.entity.*;import com.dtm.platform.repository.*;import com.dtm.platform.dto.*;import com.dtm.platform.service.*;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.MediaType;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import java.time.Instant;import java.util.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test") class PlatformIntegrationTest {
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){r.add("app.jwt-secret",()->Base64.getEncoder().encodeToString(new byte[48]));r.add("spring.datasource.password",()->"");}
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired ContentService content;@Autowired ProjectRepository projects;@Autowired UserRepository users;@Autowired RoleRepository roles;@Autowired PasswordEncoder passwords;@Autowired JwtEncoder encoder;
 String token(String role,Instant expiry){var now=Instant.now();return encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),JwtClaimsSet.builder().issuer("dtm-platform").subject("otp:"+com.dtm.platform.security.OtpIdentity.hash("6999999999")).issuedAt(now.minusSeconds(3600)).expiresAt(expiry).claim("roles",List.of(role)).claim("authMethod","otp").build())).getTokenValue();}
 @Test void anonymousCannotReadAdmin()throws Exception{mvc.perform(get("/api/v1/admin/projects")).andExpect(status().isUnauthorized());}
 @Test void hiddenContentStaysPrivateAndVersionsConflict()throws Exception{var input=new ContentInput("Draft","draft-"+UUID.randomUUID(),"Private draft","Tests","CONCEPT",false,false,0,Map.of(),null);var row=content.save("projects",null,input);mvc.perform(get("/api/v1/projects/"+row.slug())).andExpect(status().isNotFound());mvc.perform(get("/api/v1/admin/projects/"+row.id()).header("Authorization","Bearer "+token("ADMIN",Instant.now().plusSeconds(600)))).andExpect(status().isOk());var changed=new ContentInput("Updated",row.slug(),"Private draft","Tests","CONCEPT",false,false,0,Map.of(),row.version());content.save("projects",String.valueOf(row.id()),changed);mvc.perform(put("/api/v1/admin/projects/"+row.id()).header("Authorization","Bearer "+token("ADMIN",Instant.now().plusSeconds(600))).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(changed))).andExpect(status().isConflict());}
 @Test void editorCannotDelete()throws Exception{mvc.perform(delete("/api/v1/admin/projects/1").header("Authorization","Bearer "+token("EDITOR",Instant.now().plusSeconds(600)))).andExpect(status().isForbidden());}
 @Test void expiredTokenIsRejected()throws Exception{mvc.perform(get("/api/v1/admin/projects").header("Authorization","Bearer "+token("ADMIN",Instant.now().minusSeconds(120)))).andExpect(status().isUnauthorized());}
 @Test void validJwtCanReadAdmin()throws Exception{mvc.perform(get("/api/v1/admin/projects").header("Authorization","Bearer "+token("EDITOR",Instant.now().plusSeconds(600)))).andExpect(status().isOk());}
 @Test void invalidContactIsRejected()throws Exception{mvc.perform(post("/api/v1/contact").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Test\",\"email\":\"invalid\",\"message\":\"short\"}")).andExpect(status().isBadRequest());}
 @Test void contactCannotExposeLeadDetails()throws Exception{mvc.perform(post("/api/v1/contact").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Test Sender\",\"email\":\"test@example.test\",\"message\":\"An integration test project brief\",\"submissionKey\":\"integration-contact-01\"}")).andExpect(status().isCreated()).andExpect(jsonPath("$.email").doesNotExist());mvc.perform(get("/api/v1/admin/contact")).andExpect(status().isUnauthorized());}
 @Test void analyticsRequiresConsent()throws Exception{mvc.perform(post("/api/v1/analytics/events").contentType(MediaType.APPLICATION_JSON).content("{\"eventType\":\"PAGE_VIEW\",\"resource\":\"workspace\",\"consent\":false}")).andExpect(status().isBadRequest());}
 @Test void unknownEventIsRejected()throws Exception{mvc.perform(post("/api/v1/analytics/events").contentType(MediaType.APPLICATION_JSON).content("{\"eventType\":\"FINGERPRINT\",\"resource\":\"workspace\",\"consent\":true}")).andExpect(status().isBadRequest());}
}
